const AUTO_APPLY_SEVERITIES = ['low', 'medium', 'high', 'critical'] as const;

export type AutoApplySeverity = (typeof AUTO_APPLY_SEVERITIES)[number];

/**
 * Narrow a value read from the database to a known severity level.
 * The column is untyped/nullable at the storage layer, so anything that is not
 * one of the four known levels is rejected and the caller falls back to a default.
 */
function isAutoApplySeverity(value: unknown): value is AutoApplySeverity {
  return typeof value === 'string' && (AUTO_APPLY_SEVERITIES as readonly string[]).includes(value);
}

export interface AutoApplyConfig {
  enabled: boolean;
  maxSeverity: AutoApplySeverity;
  activeProfile: string;
  profileLocked: boolean;
}
